add_filter( 'woocommerce_continue_shopping_redirect', 'perfectpixel_continue_shopping_redirect' );

function perfectpixel_continue_shopping_redirect( $url ) {
	$custom = trim( '{{continue_shopping_url}}' );
	if ( '' === $custom ) {
		return wc_get_page_permalink( 'shop' );
	}
	return 0 === strpos( $custom, '/' ) ? home_url( $custom ) : $custom;
}
